/*@ Import Coq Require Import Dwconv.RvvCursor */
/*@ Extern Coq (dw_rvv_weight_cursor:Z->Z->Z->Z->Prop) */
void test_rvv(
    size_t channels,
    size_t output_width,
    const float** input,
    const float* weights,
    float* output,
    intptr_t input_stride,
    size_t output_increment,
    size_t input_offset,
    size_t input_pixel_stride,
    const float* zero,
    const struct xnn_f32_minmax_params* restrict params)
/*@ With (D:DwProgram) (F:DwROMap) (P:DwPtrMap) (W:list Z) (O:DwOutput) (lo:fp32) (hi:fp32) Require params!=0 && channels>0 && output_width>0 && channels==dw_channels(D) && output_width==dw_width(D) && input==dw_input(D) && weights==dw_weights(D) && output==dw_out(D) && input_stride==dw_input_stride(D) && output_increment==dw_out_increment(D) && input_offset==dw_offset(D) && input_pixel_stride==dw_pixel_stride(D) && zero==dw_zero_ptr(D) && dw_valid(F,P,W,D) && dw_distinct(W) && dw_present(F,&(params->scalar.min)) && dw_present(F,&(params->scalar.max)) && dw_same(lo,dw_get(F,&(params->scalar.min))) && dw_same(hi,dw_get(F,&(params->scalar.max))) && dw_data(F) * dw_ptr_data(P) * dw_output(W,O) Ensure dw_data(F) * dw_ptr_data(P) * dw_output(W,dw_rvv_result(F,P,D,lo,hi,O)) */
{
  /*@ Assert channels==dw_channels(D) && output_width==dw_width(D) && input==dw_input(D) && weights==dw_weights(D) && output==dw_out(D) && input_stride==dw_input_stride(D) && output_increment==dw_out_increment(D) && input_offset==dw_offset(D) && input_pixel_stride==dw_pixel_stride(D) && zero==dw_zero_ptr(D) && params==params@pre && params!=0 && channels>0 && output_width>0 && dw_valid(F,P,W,D) && dw_distinct(W) && sizeof(float)==4 && sizeof(float*)==8 && dw_present(F,&(params->scalar.min)) && dw_present(F,&(params->scalar.max)) && dw_same(lo,dw_get(F,&(params->scalar.min))) && dw_same(hi,dw_get(F,&(params->scalar.max))) && dw_data(F) * dw_ptr_data(P) * dw_output(W,O) */
  dw_assert((channels != 0));
  dw_assert((output_width != 0));
  /*@ Inv Assert channels==dw_channels(D) && weights==dw_weights(D) && input_stride==dw_input_stride(D) && output_increment==dw_out_increment(D) && input_pixel_stride==dw_pixel_stride(D) && zero==dw_zero_ptr(D) && params==params@pre && params!=0 && channels>0 && dw_width(D)>0 && dw_valid(F,P,W,D) && dw_distinct(W) && sizeof(float)==4 && sizeof(float*)==8 && dw_present(F,&(params->scalar.min)) && dw_present(F,&(params->scalar.max)) && dw_same(lo,dw_get(F,&(params->scalar.min))) && dw_same(hi,dw_get(F,&(params->scalar.max))) && 0<=output_width && output_width<=dw_width(D) && input==dw_table(D,(dw_width(D)-output_width)) && input_offset==dw_offset_at(D,(dw_width(D)-output_width)) && output==dw_output_at(D,(dw_width(D)-output_width)) && dw_data(F) * dw_ptr_data(P) * dw_output(W,dw_rvv_progress(F,P,D,(dw_width(D)-output_width),0,lo,hi,O)) */
  while (output_width != 0) {
    /*@ Assert channels==dw_channels(D) && weights==dw_weights(D) && input_stride==dw_input_stride(D) && output_increment==dw_out_increment(D) && input_pixel_stride==dw_pixel_stride(D) && zero==dw_zero_ptr(D) && params==params@pre && params!=0 && channels>0 && dw_width(D)>0 && dw_valid(F,P,W,D) && dw_distinct(W) && sizeof(float)==4 && sizeof(float*)==8 && dw_present(F,&(params->scalar.min)) && dw_present(F,&(params->scalar.max)) && dw_same(lo,dw_get(F,&(params->scalar.min))) && dw_same(hi,dw_get(F,&(params->scalar.max))) && 0<output_width && output_width<=dw_width(D) && input==dw_table(D,(dw_width(D)-output_width)) && input_offset==dw_offset_at(D,(dw_width(D)-output_width)) && output==dw_output_at(D,(dw_width(D)-output_width)) && dw_ptr_present(P,pointer_offset(input,0,float*)) && dw_ptr_present(P,pointer_offset(input,1,float*)) && dw_ptr_present(P,pointer_offset(input,2,float*)) && dw_ptr_get(P,pointer_offset(input,0,float*))!=0 && dw_ptr_get(P,pointer_offset(input,1,float*))!=0 && dw_ptr_get(P,pointer_offset(input,2,float*))!=0 && dw_data(F) * dw_ptr_data(P) * dw_output(W,dw_rvv_progress(F,P,D,(dw_width(D)-output_width),0,lo,hi,O)) */
    const float* i0 = input[0];
    dw_assert((i0 != ((void*)0)));
    if (i0 != zero) {
      i0 = (const float*) ((uintptr_t) i0 + input_offset);
    }
    const float* i1 = input[1];
    dw_assert((i1 != ((void*)0)));
    if (i1 != zero) {
      i1 = (const float*) ((uintptr_t) i1 + input_offset);
    }
    const float* i2 = input[2];
    dw_assert((i2 != ((void*)0)));
    if (i2 != zero) {
      i2 = (const float*) ((uintptr_t) i2 + input_offset);
    }
    input = (const float**) ((uintptr_t) input + input_stride);
    size_t c = channels;
    const float* w = weights;
    /*@ Inv Assert channels==dw_channels(D) && weights==dw_weights(D) && input_stride==dw_input_stride(D) && output_increment==dw_out_increment(D) && input_pixel_stride==dw_pixel_stride(D) && zero==dw_zero_ptr(D) && params==params@pre && params!=0 && channels>0 && dw_width(D)>0 && dw_valid(F,P,W,D) && dw_distinct(W) && sizeof(float)==4 && sizeof(float*)==8 && dw_present(F,&(params->scalar.min)) && dw_present(F,&(params->scalar.max)) && dw_same(lo,dw_get(F,&(params->scalar.min))) && dw_same(hi,dw_get(F,&(params->scalar.max))) && 0<output_width && output_width<=dw_width(D) && input==dw_table(D,(dw_width(D)-output_width)+1) && input_offset==dw_offset_at(D,(dw_width(D)-output_width)) && 0<=c && c<=channels && dw_aligned_cursor(channels,c) && output==dw_output_at(D,(dw_width(D)-output_width))+4*(channels-c) && dw_rvv_weight_cursor(channels,c,w,weights) && i0==dw_input_row(P,D,(dw_width(D)-output_width),0)+4*(channels-c) && i1==dw_input_row(P,D,(dw_width(D)-output_width),1)+4*(channels-c) && i2==dw_input_row(P,D,(dw_width(D)-output_width),2)+4*(channels-c) && dw_data(F) * dw_ptr_data(P) * dw_output(W,dw_rvv_progress(F,P,D,(dw_width(D)-output_width),(channels-c),lo,hi,O)) */
    while (c > 0) {
      size_t vl = __riscv_vsetvl_e32m4(c < 4 ? c : 4);
      /*@ Assert channels==dw_channels(D) && weights==dw_weights(D) && input_stride==dw_input_stride(D) && output_increment==dw_out_increment(D) && input_pixel_stride==dw_pixel_stride(D) && zero==dw_zero_ptr(D) && params==params@pre && params!=0 && channels>0 && dw_width(D)>0 && dw_valid(F,P,W,D) && dw_distinct(W) && sizeof(float)==4 && sizeof(float*)==8 && dw_present(F,&(params->scalar.min)) && dw_present(F,&(params->scalar.max)) && dw_same(lo,dw_get(F,&(params->scalar.min))) && dw_same(hi,dw_get(F,&(params->scalar.max))) && 0<output_width && output_width<=dw_width(D) && input==dw_table(D,(dw_width(D)-output_width)+1) && input_offset==dw_offset_at(D,(dw_width(D)-output_width)) && 0<=c && c<=channels && ((channels-c))%4==0 && output==dw_output_at(D,(dw_width(D)-output_width))+4*(channels-c) && w==pointer_offset(weights,4*(channels-c),float) && i0==dw_input_row(P,D,(dw_width(D)-output_width),0)+4*(channels-c) && i1==dw_input_row(P,D,(dw_width(D)-output_width),1)+4*(channels-c) && i2==dw_input_row(P,D,(dw_width(D)-output_width),2)+4*(channels-c) && c>0 && dw_window(F,i0,vl) && dw_window(F,i1,vl) && dw_window(F,i2,vl) && dw_window(F,pointer_offset(w,0,float),vl) && dw_window(F,pointer_offset(w,4,float),vl) && dw_window(F,pointer_offset(w,8,float),vl) && dw_window(F,pointer_offset(w,12,float),vl) && vl==dw_take(c) && 1<=vl && vl<=4 && dw_write_window(W,output,vl) && dw_data(F) * dw_ptr_data(P) * dw_output(W,dw_rvv_progress(F,P,D,(dw_width(D)-output_width),(channels-c),lo,hi,O)) */
      vfloat32m4_t vacc = __riscv_vle32_v_f32m4(w, vl); w += 4;
      vfloat32m4_t vi0 = __riscv_vle32_v_f32m4(i0, vl); i0 += vl;
      vfloat32m4_t vk0 = __riscv_vle32_v_f32m4(w, vl); w += 4;
      vacc = __riscv_vfmacc_vv_f32m4(vacc, vi0, vk0, vl) /*@ where a=0,b=0,c=0 */;
      vfloat32m4_t vi1 = __riscv_vle32_v_f32m4(i1, vl); i1 += vl;
      vfloat32m4_t vk1 = __riscv_vle32_v_f32m4(w, vl); w += 4;
      vfloat32m4_t vacc1 = __riscv_vfmul_vv_f32m4(vi1, vk1, vl) /*@ where a=0,b=0 */;
      vfloat32m4_t vi2 = __riscv_vle32_v_f32m4(i2, vl); i2 += vl;
      vfloat32m4_t vk2 = __riscv_vle32_v_f32m4(w, vl); w += 4;
      vacc = __riscv_vfmacc_vv_f32m4(vacc, vi2, vk2, vl) /*@ where a=0,b=0,c=0 */;
      vacc = __riscv_vfadd_vv_f32m4(vacc, vacc1, vl) /*@ where a=0,b=0 */;
      vbool8_t nan_acc = dw_nanmask(&(vacc),&(vacc),(vl));
      vfloat32m4_t vlo = __riscv_vfmv_v_f_f32m4(params->scalar.min, vl);
      vbool8_t nan_lo = dw_nanmask(&(vlo),&(vlo),(vl));
      vfloat32m4_t vmaxed = __riscv_vfmax_vf_f32m4(vacc, params->scalar.min, vl) /*@ where a=0 */;
      vmaxed = __riscv_vmerge_vvm_f32m4(vmaxed, vacc, nan_acc, vl) /*@ where a=0,b=0,mask=0 */;
      vacc = __riscv_vmerge_vvm_f32m4(vmaxed, vlo, nan_lo, vl) /*@ where a=0,b=0,mask=0 */;
      vbool8_t nan_maxed = dw_nanmask(&(vacc),&(vacc),(vl));
      vfloat32m4_t vhi = __riscv_vfmv_v_f_f32m4(params->scalar.max, vl);
      vbool8_t nan_hi = dw_nanmask(&(vhi),&(vhi),(vl));
      vfloat32m4_t vminned = __riscv_vfmin_vf_f32m4(vacc, params->scalar.max, vl) /*@ where a=0 */;
      vminned = __riscv_vmerge_vvm_f32m4(vminned, vacc, nan_maxed, vl) /*@ where a=0,b=0,mask=0 */;
      vacc = __riscv_vmerge_vvm_f32m4(vminned, vhi, nan_hi, vl) /*@ where a=0,b=0,mask=0 */;
      dw_rvv_store_view((output),&(vacc),(vl)); output += vl;
      c -= vl;
    }
    input_offset += input_pixel_stride;
    output = (float*) ((uintptr_t) output + output_increment);
    --output_width;
  }
}
